<section class="section"><div class="site-container"><div class="section-heading"><div><h2>Recorded price trend</h2><p>Recent average prices in date order; use the product filter above to focus this history.</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Product</th><th>Market</th><th>Average</th></tr></thead><tbody><?php if($trends===[]):?><tr><td colspan="4">No price history has been recorded yet.</td></tr><?php else:foreach($trends as $trend):?><tr><td><?= e(date('j M Y',strtotime($trend['price_date']))) ?></td><td><?= e($trend['name']) ?></td><td><?= e($trend['district']) ?></td><td><strong>Rs. <?= number_format((float)$trend['average_price'],2) ?>/<?= e($trend['unit']) ?></strong></td></tr><?php endforeach;endif;?></tbody></table></div></div></section>
